#[inline]
fn destack_input_event_set_exclusive_grab_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    handle: resource::InputDeviceHandle,
    enable: bool,
) -> RuntimeResult<()> {
    let _ = (&handle, &enable);

    binding.trace().run_binding_without_context(
        INPUT_EVENT_SET_EXCLUSIVE_GRAB,
        binding.replay_payload_for(INPUT_EVENT_SET_EXCLUSIVE_GRAB)?,
        || match world {
            RuntimeWorld::Host => unsafe { platform_native::destack_input_set_exclusive_grab(binding, handle, enable) },
            RuntimeWorld::Simulation => unsafe { platform_simulation_native::destack_input_set_exclusive_grab(binding, handle, enable) },
        },
        |result| {
            if let Ok(()) = result {
                let result_recorded = ();
                let payload = InputEventSetExclusiveGrabReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    InputEventSetExclusiveGrabReplayRecord {
                        result,
                    }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(()) => Ok(()),
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

