                        let value_native_contacts_decoded_x = value_native_contacts_item.x;
                        let value_native_contacts_decoded_y = value_native_contacts_item.y;
                        let value_native_contacts_decoded_pressure = value_native_contacts_item.pressure;
                        let value_native_contacts_decoded_radius_x = value_native_contacts_item.radius_x;
                        let value_native_contacts_decoded_radius_y = value_native_contacts_item.radius_y;
