#[inline]
fn destack_input_keyboard_state_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
    handle: resource::InputDeviceHandle,
) -> RuntimeResult<vm::Value> {
    let result = binding.trace().run_binding(
        INPUT_KEYBOARD_STATE,
        binding.replay_payload_for(INPUT_KEYBOARD_STATE)?,
        context,
        |context| {
            match world {
                RuntimeWorld::Host => platform_vm::destack_input_keyboard_state(binding, context, handle),
                RuntimeWorld::Simulation => platform_simulation_vm::destack_input_keyboard_state(binding, context, handle),
            }
        },
        |context, result| {
            let _ = &context;
            if let Ok(value) = result {
                let result_value: InputKeyboardStateVm = value.clone();
                let result_recorded_timestamp_ns = result_value.timestamp_ns;
                let result_recorded_sequence = result_value.sequence;
                let result_recorded_device_id = {
                    let result_recorded_device_id_ref = context.string_ref(result_value.device_id).map_err(|error| RuntimeError::from(error).boxed())?;
                    result_recorded_device_id_ref.as_str().to_string()
                };
                let result_recorded_modifiers = result_value.modifiers;
                let result_recorded_pressed_codes_raw = result_value.pressed_codes.raw_values(context)?;
                let mut result_recorded_pressed_codes = Vec::with_capacity(result_recorded_pressed_codes_raw.len());
                for result_recorded_pressed_codes_item_value in result_recorded_pressed_codes_raw {
                    let result_recorded_pressed_codes_item = decode_uint32(result_recorded_pressed_codes_item_value, "result_recorded_pressed_codes_item", "item")?;
                    let result_recorded_pressed_codes_item_recorded = result_recorded_pressed_codes_item;
                    result_recorded_pressed_codes.push(result_recorded_pressed_codes_item_recorded);
                }
                let result_recorded_pressed_scan_codes_raw = result_value.pressed_scan_codes.raw_values(context)?;
                let mut result_recorded_pressed_scan_codes = Vec::with_capacity(result_recorded_pressed_scan_codes_raw.len());
                for result_recorded_pressed_scan_codes_item_value in result_recorded_pressed_scan_codes_raw {
                    let result_recorded_pressed_scan_codes_item = decode_uint32(result_recorded_pressed_scan_codes_item_value, "result_recorded_pressed_scan_codes_item", "item")?;
                    let result_recorded_pressed_scan_codes_item_recorded = result_recorded_pressed_scan_codes_item;
                    result_recorded_pressed_scan_codes.push(result_recorded_pressed_scan_codes_item_recorded);
                }
                let result_recorded = InputkeyboardstateReplayRecord {
                    timestamp_ns: result_recorded_timestamp_ns,
                    sequence: result_recorded_sequence,
                    device_id: result_recorded_device_id,
                    modifiers: result_recorded_modifiers,
                    pressed_codes: result_recorded_pressed_codes,
                    pressed_scan_codes: result_recorded_pressed_scan_codes,
                };
                let payload = InputKeyboardStateReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    InputKeyboardStateReplayRecord {
                        result,
                    }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |context, payload| {
            let _ = &context;
            // replay result
            match payload.result {
                Ok(value) => {
                    let vm_result_timestamp_ns = value.timestamp_ns;
                    let vm_result_sequence = value.sequence;
                    let vm_result_device_id_value = context.intern_string(value.device_id.as_str());
                    let vm_result_device_id = vm::StringHandle::new(vm_result_device_id_value);
                    let vm_result_modifiers = value.modifiers;
                    let mut vm_result_pressed_codes_values = Vec::with_capacity(value.pressed_codes.len());
                    for vm_result_pressed_codes_item in value.pressed_codes.iter().cloned() {
                        let vm_result_pressed_codes_item_value = vm_result_pressed_codes_item;
                        vm_result_pressed_codes_values.push(vm_result_pressed_codes_item_value);
                    }
                    let vm_result_pressed_codes = VmArray::from_values(context, &vm_result_pressed_codes_values)?;
                    let mut vm_result_pressed_scan_codes_values = Vec::with_capacity(value.pressed_scan_codes.len());
                    for vm_result_pressed_scan_codes_item in value.pressed_scan_codes.iter().cloned() {
                        let vm_result_pressed_scan_codes_item_value = vm_result_pressed_scan_codes_item;
                        vm_result_pressed_scan_codes_values.push(vm_result_pressed_scan_codes_item_value);
                    }
                    let vm_result_pressed_scan_codes = VmArray::from_values(context, &vm_result_pressed_scan_codes_values)?;
                    let vm_result = InputKeyboardStateVm {
                        timestamp_ns: vm_result_timestamp_ns,
                        sequence: vm_result_sequence,
                        device_id: vm_result_device_id,
                        modifiers: vm_result_modifiers,
                        pressed_codes: vm_result_pressed_codes,
                        pressed_scan_codes: vm_result_pressed_scan_codes,
                    };
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_input_keyboard_state_result(context, result)?;
    Ok(result)
}

